def test_parse_collision_payload_retains_synthetic_root_as_uint_without_changing_ids(parse_values):
    from gita.index.model import ParseResult

    ordinary = ParseResult(**parse_values)
    root = replace(ordinary.definitions[0], synthetic_root=True)
    synthetic = replace(ordinary, definitions=(root,))
    assert ordinary.definitions[0].synthetic_root is False
    assert synthetic.definitions[0].synthetic_root is True
    assert root.id == ordinary.definitions[0].id
    assert root.version_id == ordinary.definitions[0].version_id
    assert synthetic.id == ordinary.id
    assert synthetic.key_fields() == ordinary.key_fields()
    assert synthetic.fields() != ordinary.fields()
    ordinary_payload = canonical_encode("par1", ordinary.fields())
    synthetic_payload = canonical_encode("par1", synthetic.fields())
    differences = [
        offset for offset, (before, after) in enumerate(zip(ordinary_payload, synthetic_payload, strict=True))
        if before != after
    ]
    assert len(differences) == 1
    offset = differences[0]
    assert ordinary_payload[offset - 9:offset + 1] == bytes.fromhex("0175 0000000000000000")
    assert synthetic_payload[offset - 9:offset + 1] == bytes.fromhex("0175 0000000000000001")
    with pytest.raises(IndexContractError) as caught:
        require_same_payload(ordinary_payload, synthetic_payload)
    assert caught.value.code == "digest_collision"


