def test_context_identity_covers_boundary_ordered_parents_and_policy(records):
    context = records["ctx1"]
    first, second = GitOid("sha1", b"x" * 20), GitOid("sha1", b"y" * 20)
    bounded = replace(context, boundary="bounded", parents=(first, second))
    assert bounded.id != replace(bounded, parents=(second, first)).id
    for changes in ({"anchor": first}, {"boundary": "bounded"}, {"parse_fingerprint": b"q" * 32},
                    {"match_fingerprint": b"n" * 32}, {"limits": (("max_bytes", 8192),)}):
        assert replace(context, **changes).id != context.id
    for limits in (tuple(reversed(LIMITS)), (("bytes", 1), ("bytes", 2)), (("bytes", -1),)):
        with pytest.raises(IndexContractError):
            replace(context, limits=limits)


@pytest.mark.parametrize("reason", ("root", "observed_addition_with_complete_predecessor"))
def test_complete_seed_payload_excludes_optional_evidence(records, reason):
    seed = replace(records["eid1"], reason=reason)
    assert seed.id == content_id("eid1", (CONTEXT_ID, seed.commit.fields(), DESTINATION_ID, reason))
    for changes in ({"context_id": "ctx1_" + "99" * 32}, {"commit": GitOid("sha1", b"z" * 20)},
                    {"occurrence_id": SOURCE_ID}):
        assert replace(seed, **changes).id != seed.id


@pytest.mark.parametrize("reason", ("bounded", "shallow", "missing_parent", "parse_gap", "ambiguous",
                                  "unmatched", "kind_changed", "side_parent_origin_unresolved"))
def test_observed_seed_requires_evidence_and_never_aliases_genesis(records, reason):
    seed = replace(records["oeid1"], reason=reason)
    assert seed.id == content_id("oeid1", (CONTEXT_ID, seed.commit.fields(), DESTINATION_ID, reason, EVIDENCE_DIGEST))
    assert seed.id != records["eid1"].id
    assert replace(seed, evidence_digest=b"f" * 32).id != seed.id
    for evidence in (None, b"", b"e" * 31, b"e" * 33):
        with pytest.raises(IndexContractError):
            replace(seed, evidence_digest=evidence)


def test_typed_error_and_payload_collision_contract():
    error = IndexContractError("invalid_record", "bad record")
    assert isinstance(error, ValueError) and error.code == "invalid_record"
    assert "bad record" in str(error)
    assert require_same_payload(b"payload", b"payload") is None
    with pytest.raises(IndexContractError) as caught:
        require_same_payload(b"payload", b"different")
    assert caught.value.code == "digest_collision"


def test_enum_names_and_values_are_stable():
    for enum, names in (
        (ParseStatus, ("complete", "unsupported_language", "unsupported_encoding", "parse_error",
                       "oversized", "definition_limit", "representation_limit")),
        (LinkStatus, ("accepted", "candidate", "rejected", "ambiguous")),
        (LifeCycle, ("present", "removed", "absent", "unknown")),
    ):
        assert {member.value for member in enum} == set(names)
        for name in names:
            assert enum[name.upper()].value == name


def test_links_require_canonical_evidence_and_never_accept_similarity(records):
    link = records["lnk1"]
    for changes in ({"method": "similarity"}, {"evidence": ()},
                    {"evidence": (("key", 1), ("key", 2))}, {"evidence": tuple(reversed(EVIDENCE))}):
        with pytest.raises(IndexContractError):
            replace(link, **changes)
    for status in (LinkStatus.CANDIDATE, LinkStatus.REJECTED, LinkStatus.AMBIGUOUS):
        assert replace(link, method="similarity", status=status).status is status
    assert replace(link, destination=SOURCE_ID).source == SOURCE_ID


def test_link_ids_cover_edge_endpoints_status_method_reason_and_evidence(records):
    link = records["lnk1"]
    for changes in ({"context_id": "ctx1_" + "99" * 32}, {"parent": link.commit}, {"commit": link.parent},
                    {"source": DESTINATION_ID}, {"destination": SOURCE_ID}, {"status": LinkStatus.CANDIDATE},
                    {"method": "exact_own"}, {"reason": "full_equality"}, {"evidence": (("population", 2),)}):
        assert replace(link, **changes).id != link.id


@pytest.mark.parametrize("material,flags", [
    (True, ("added", "removed", "renamed", "moved", "signature_changed", "body_changed", "own_content_changed")),
    (False, ("cosmetic", "descendant_changed", "lineage_gap", "observed", "representation_unknown", "mode_changed")),
])
def test_event_materiality_is_an_independent_flag_projection(records, material, flags):
    for flag in flags:
        event = replace(records["evt1"], flags=(flag,))
        assert event.material is material
        assert replace(event, flags=(flag, "moved") if flag != "moved" else (flag,)).material is True


def test_event_ids_sort_flags_and_cover_context_identity_edge_endpoints_and_decision(records):
    event = records["evt1"]
    assert replace(event, flags=("renamed", "body_changed")).id == event.id
    for changes in ({"context_id": "ctx1_" + "99" * 32}, {"eid": "oeid1_" + "99" * 32},
                    {"parent": None}, {"commit": event.parent}, {"source": None}, {"destination": None},
                    {"flags": ("body_changed",)}, {"decision_id": None}):
        assert replace(event, **changes).id != event.id
    assert replace(event, parent=None, source=None, flags=("added",), decision_id=None).material is True


